# Social golfer 9-3-7: use AG(3,3) affine space which gives 13 parallel classes
# 27 points = GF(3)^3. Lines = {P + t*D : t in GF(3)} for direction D != 0.
# Directions equivalent under scaling (multiply by 2 = -1). 
# So 26/2 = 13 direction classes -> 13 parallel classes (weeks)

from itertools import product

points = list(product(range(3), repeat=3))
pt_idx = {p:i for i,p in enumerate(points)}

# Generate direction representatives: pick nonzero vectors with first nonzero coord = 1
dirs = []
for d in points:
    if d == (0,0,0): continue
    # find first nonzero
    for c in d:
        if c != 0:
            if c == 1:
                dirs.append(d)
            break
assert len(dirs) == 13

def add(p, d, t):
    return tuple((p[i] + t*d[i]) % 3 for i in range(3))

schedule = []  # schedule[w] = list of 9 groups (each group = list of 3 golfer indices)
for d in dirs:
    # partition points into lines with direction d
    used = [False]*27
    groups = []
    for p in points:
        if used[pt_idx[p]]: continue
        line = [add(p,d,t) for t in range(3)]
        for q in line:
            used[pt_idx[q]] = True
        groups.append(sorted(pt_idx[q] for q in line))
    assert len(groups) == 9
    schedule.append(groups)

# Verify pair constraint
pairs_seen = {}
for w,weekgrps in enumerate(schedule):
    for g in weekgrps:
        for i in range(3):
            for j in range(i+1,3):
                pair = (g[i],g[j])
                assert pair not in pairs_seen, (pair, pairs_seen[pair], w)
                pairs_seen[pair] = w

# Take first 7 weeks
schedule = schedule[:7]

# Build flat list: entry w*27 + p = group of golfer p in week w
result = [0]*(7*27)
for w in range(7):
    for gi, grp in enumerate(schedule[w]):
        for p in grp:
            result[w*27 + p] = gi

print(len(result))
print(result)
